// config.js is generated by extension/build/build.mjs from APP_URL
import { API_BASE } from "./config.js";

let eventSource = null;
let mercureConfig = null;

// ─── Captcha / block detection ────────────────────────────────────────────
//
// Runs inside the target tab's page context (no extension APIs available here).
// Returns true if the page looks like a CAPTCHA or block screen.
//
function detectCaptchaInPage() {
  const html = document.documentElement.innerHTML.toLowerCase();
  const title = document.title.toLowerCase();
  const url = location.href.toLowerCase();

  const HTML_SIGNALS = [
    "cf-browser-verification",   // Cloudflare classic
    "cf-challenge",              // Cloudflare challenge
    "cloudflare ray id",
    "g-recaptcha",               // Google reCAPTCHA
    "h-captcha",                 // hCaptcha
    "data-hcaptcha-response",
    "__cf_chl",                  // Cloudflare challenge form
    "datadome",                  // DataDome
    "px-captcha",                // PerimeterX
    "_pxCaptcha",
    "turnstile",                 // Cloudflare Turnstile
    "challenge-form",
    "interstitial-wrapper",      // LinkedIn interstitial
    "authwall",                  // LinkedIn auth wall
  ];

  const TITLE_SIGNALS = [
    "robot", "captcha", "access denied", "blocked",
    "security check", "human verification", "attention required",
    "just a moment",             // Cloudflare waiting room
    "verification required",
  ];

  const URL_SIGNALS = [
    "captcha", "challenge", "blocked", "checkpoint",
  ];

  if (HTML_SIGNALS.some(s => html.includes(s))) return true;
  if (TITLE_SIGNALS.some(s => title.includes(s))) return true;
  if (URL_SIGNALS.some(s => url.includes(s))) return true;

  // HTTP 403 / 429 sometimes render a short page with no main content
  const bodyText = (document.body?.innerText || "").trim();
  if (bodyText.length < 300 && (title.includes("403") || title.includes("429") || title.includes("denied"))) return true;

  return false;
}

// ─── Blocked-tabs registry (in-memory + chrome.storage.session) ───────────

async function getBlockedTabs() {
  const data = await chrome.storage.session.get("blockedTabs");
  return data.blockedTabs || {};
}

async function setBlockedTabs(map) {
  await chrome.storage.session.set({ blockedTabs: map });
}

async function updateActionBadge(count) {
  try {
    if (count > 0) {
      await chrome.action.setBadgeText({ text: String(count) });
      await chrome.action.setBadgeBackgroundColor({ color: "#EF4444" });
    } else {
      await chrome.action.setBadgeText({ text: "" });
    }
  } catch {}
}

async function addBlockedTab(tabId, entry) {
  const map = await getBlockedTabs();
  map[tabId] = entry;
  await setBlockedTabs(map);
  await updateActionBadge(Object.keys(map).length);
}

async function removeBlockedTab(tabId) {
  const map = await getBlockedTabs();
  delete map[tabId];
  await setBlockedTabs(map);
  await updateActionBadge(Object.keys(map).length);
}

// ─── Tab-completion watcher ───────────────────────────────────────────────
// When a blocked tab finishes navigating (user solved captcha and page reloaded),
// automatically retry extraction.

chrome.tabs.onUpdated.addListener(async (tabId, changeInfo) => {
  if (changeInfo.status !== "complete") return;

  const map = await getBlockedTabs();
  if (!(tabId in map)) return;

  const entry = map[tabId];
  console.log(`Blocked tab ${tabId} finished loading — re-checking for captcha`);

  // Give JS a moment to render
  await new Promise(r => setTimeout(r, 2000));

  const isCaptcha = await checkTabForCaptcha(tabId);
  if (isCaptcha) {
    console.log(`Tab ${tabId} still blocked — waiting for user`);
    // Keep it in the map; popup already shows it
    return;
  }

  // Captcha is solved — extract and submit
  console.log(`Tab ${tabId} looks unblocked — extracting HTML`);
  await extractAndSubmit(tabId, entry);
});

// Clean up blockedTabs registry if the user closes the blocked tab manually
chrome.tabs.onRemoved.addListener(async (tabId) => {
  const map = await getBlockedTabs();
  if (tabId in map) {
    console.log(`Blocked tab ${tabId} was closed manually`);
    await removeBlockedTab(tabId);
  }
});

// ─── Core helpers ─────────────────────────────────────────────────────────

async function checkTabForCaptcha(tabId) {
  try {
    const results = await chrome.scripting.executeScript({
      target: { tabId },
      func: detectCaptchaInPage,
    });
    return results?.[0]?.result === true;
  } catch {
    return false;
  }
}

async function extractAndSubmit(tabId, entry) {
  try {
    const results = await chrome.scripting.executeScript({
      target: { tabId },
      func: () => document.documentElement.outerHTML,
    });

    const html = results?.[0]?.result;
    if (html) {
      await submitTaskResult(entry.task_id, entry.url, html);
    }
  } catch (e) {
    console.error("Failed to extract HTML after captcha solve:", e);
  } finally {
    await removeBlockedTab(tabId);
    try { await chrome.tabs.remove(tabId); } catch {}
  }
}

// ─── Context Menu ──────────────────────────────────────────────────────────

function setupContextMenu() {
  chrome.contextMenus.removeAll(() => {
    chrome.contextMenus.create({
      id: "add-link-vacancy",
      title: "Add this vacancy",
      contexts: ["link"],
    });
    chrome.contextMenus.create({
      id: "add-page-vacancy",
      title: "Add this vacancy (current page)",
      contexts: ["page"],
    });
  });
}

setupContextMenu();
chrome.runtime.onInstalled.addListener(setupContextMenu);
chrome.runtime.onStartup.addListener(setupContextMenu);

chrome.contextMenus.onClicked.addListener(async (info, tab) => {
  if (info.menuItemId === "add-link-vacancy") {
    const url = info.linkUrl;
    if (!url) return;
    try {
      await getOffscreenDocument();
      const result = await chrome.runtime.sendMessage({
        type: 'PARSE_HTML',
        url,
        html: null
      });

      if (!result?.success) {
        throw new Error(result?.error || 'Failed to parse');
      }

      const res = await fetch(`${API_BASE}/api/extension/parse_and_add`, {
        method: "POST",
        credentials: "include",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(result.data),
      });
      if (res.ok) {
        notify("Job Tracker", `Added: ${url.slice(0, 70)}`);
      } else if (res.status === 401) {
        notify("Job Tracker — Error", "Пожалуйста, авторизуйтесь в Job Tracker (Please log in)");
      } else {
        const err = await res.text().catch(() => String(res.status));
        notify("Job Tracker — Error", err.slice(0, 120));
      }
    } catch (e) {
      notify("Job Tracker — Error", e.message);
    }
  }

  if (info.menuItemId === "add-page-vacancy") {
    if (!tab) return;
    try {
      const results = await chrome.scripting.executeScript({
        target: { tabId: tab.id },
        func: () => document.documentElement.outerHTML,
      });
      const html = results?.[0]?.result ?? null;

      await getOffscreenDocument();
      const result = await chrome.runtime.sendMessage({
        type: 'PARSE_HTML',
        url: tab.url,
        html
      });

      if (!result?.success) {
        throw new Error(result?.error || 'Failed to parse');
      }

      const res = await fetch(`${API_BASE}/api/extension/parse_and_add`, {
        method: "POST",
        credentials: "include",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(result.data),
      });
      if (res.ok) {
        notify("Job Tracker", `Added: ${tab.title?.slice(0, 60) || tab.url.slice(0, 60)}`);
      } else {
        const err = await res.text().catch(() => String(res.status));
        notify("Job Tracker — Error", err.slice(0, 120));
      }
    } catch (e) {
      notify("Job Tracker — Error", e.message);
    }
  }
});

const notifTabMap = {};

function notify(title, message, tabId = null) {
  try {
    const notifId = "jt_notif_" + Date.now() + "_" + Math.random().toString(36).slice(2, 6);
    if (tabId) {
      notifTabMap[notifId] = tabId;
    }
    chrome.notifications.create(notifId, {
      type: "basic",
      iconUrl: "icon.png",
      title,
      message,
      priority: 2,
      requireInteraction: true,
    });
  } catch {
    console.log(title, message);
  }
}

chrome.notifications.onClicked.addListener(async (notifId) => {
  const tabId = notifTabMap[notifId];
  if (tabId) {
    try {
      await chrome.tabs.update(tabId, { active: true });
      const tab = await chrome.tabs.get(tabId);
      if (tab?.windowId) {
        await chrome.windows.update(tab.windowId, { focused: true });
      }
    } catch (e) {
      console.error("Failed to focus tab on notification click:", e);
    }
  }
});

// ─── Message handler (from popup) ─────────────────────────────────────────

chrome.runtime.onMessage.addListener((msg, _sender, sendResponse) => {
  if (msg.type === "GET_BLOCKED_TABS") {
    getBlockedTabs().then(sendResponse);
    return true; // async
  }

  if (msg.type === "FOCUS_BLOCKED_TAB") {
    // Make tab visible so user can solve captcha
    chrome.tabs.update(msg.tabId, { active: true });
    // Also focus the window that contains it
    chrome.tabs.get(msg.tabId, (tab) => {
      if (tab?.windowId) chrome.windows.update(tab.windowId, { focused: true });
    });
    sendResponse({ ok: true });
  }

  if (msg.type === "RETRY_BLOCKED_TAB") {
    // User says they solved the captcha manually — extract now
    getBlockedTabs().then(async (map) => {
      const entry = map[msg.tabId];
      if (!entry) { sendResponse({ ok: false }); return; }
      await extractAndSubmit(msg.tabId, entry);
      sendResponse({ ok: true });
    });
    return true;
  }

  if (msg.type === "DISMISS_BLOCKED_TAB") {
    // User gives up — close the tab and remove from list
    removeBlockedTab(msg.tabId).then(() => {
      try { chrome.tabs.remove(msg.tabId); } catch {}
      sendResponse({ ok: true });
    });
    return true;
  }
});

// ─── Message handler (from the Job Tracker web app) ──────────────────────
// Only origins listed in manifest "externally_connectable" can reach this.

chrome.runtime.onMessageExternal.addListener((msg, _sender, sendResponse) => {
  if (msg?.type === "JOB_TRACKER_PING") {
    sendResponse({ installed: true, version: chrome.runtime.getManifest().version });
  }
});

// ─── Extension task queue (Mercure-driven) ────────────────────────────────

async function fetchMercureConfig() {
  try {
    const res = await fetch(`${API_BASE}/api/extension/mercure_config`, { credentials: "include" });
    if (!res.ok) return null;
    return await res.json();
  } catch (err) {
    console.error("Failed to fetch Mercure config:", err);
    return null;
  }
}

async function fetchTasks() {
  try {
    const res = await fetch(`${API_BASE}/api/extension/tasks`, { credentials: "include" });
    if (!res.ok) return [];
    return await res.json();
  } catch (err) {
    console.error("Failed to fetch extension tasks:", err);
    return [];
  }
}

async function getOffscreenDocument() {
  const existingContexts = await chrome.runtime.getContexts({
    contextTypes: ['OFFSCREEN_DOCUMENT'],
  });
  if (existingContexts.length > 0) return;
  await chrome.offscreen.createDocument({
    url: 'offscreen.html',
    reasons: ['DOM_PARSER'],
    justification: 'Parsing HTML of job boards locally',
  });
}

async function submitTaskResult(taskId, url, html) {
  try {
    await getOffscreenDocument();
    const result = await chrome.runtime.sendMessage({
      type: 'PARSE_HTML',
      url,
      html
    });

    if (!result?.success) {
      throw new Error(result?.error || 'Failed to parse');
    }

    const vacancyData = result.data;

    // Send parsed JSON back to backend API instead of raw HTML
    await fetch(`${API_BASE}/api/extension/tasks/${taskId}/result`, {
      method: "POST",
      credentials: "include",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(vacancyData), // We send the structured data back
    });
  } catch (err) {
    console.error("Failed to submit result:", err);
  }
}

// ─── Sequential Task Queue (1 tab at a time with timeouts) ───────────────────

const TAB_TIMEOUT_MS = 30000;          // Max time allowed for a single tab to load and extract
const PAGE_RENDER_DELAY_MS = 4000;     // Extra wait time for client-side JS/SPA hydration
const COOLDOWN_BETWEEN_TABS_MS = 2000; // Cooldown delay before opening the next tab

const taskQueue = [];
const activeTaskIds = new Set();
let isProcessingQueue = false;

function waitForTabLoad(tabId, maxWaitMs = 15000) {
  return new Promise((resolve) => {
    let timer = null;
    const updateListener = (tid, changeInfo) => {
      if (tid === tabId && changeInfo.status === "complete") {
        cleanup();
        resolve();
      }
    };
    const removeListener = (tid) => {
      if (tid === tabId) {
        cleanup();
        resolve();
      }
    };
    const cleanup = () => {
      chrome.tabs.onUpdated.removeListener(updateListener);
      chrome.tabs.onRemoved.removeListener(removeListener);
      if (timer) clearTimeout(timer);
    };
    timer = setTimeout(() => {
      cleanup();
      resolve(); // Proceed on timeout even if complete event was missed
    }, maxWaitMs);

    chrome.tabs.onUpdated.addListener(updateListener);
    chrome.tabs.onRemoved.addListener(removeListener);
  });
}

async function processTabExecution(tabId, task) {
  // Wait for tab navigation to report 'complete' (up to 15s)
  await waitForTabLoad(tabId, 15000);
  // Wait additional delay for client-side rendering (e.g. Upwork JS framework)
  await new Promise((resolve) => setTimeout(resolve, PAGE_RENDER_DELAY_MS));

  // 1. Check for captcha / block screen
  const isCaptcha = await checkTabForCaptcha(tabId);

  if (isCaptcha) {
    console.log(`Captcha detected on tab ${tabId} for ${task.url}`);
    // Store in blocked registry — tab stays open
    await addBlockedTab(tabId, {
      task_id: task.task_id,
      url: task.url,
      title: task.title || task.url,
      detected_at: Date.now(),
    });
    // Notify user via system notification with tabId attached
    notify(
      "⚠️ Job Tracker — Action Required",
      `CAPTCHA or block detected for:\n${(task.title || task.url).slice(0, 70)}\nClick to switch to this tab.`,
      tabId
    );

    // Prompt user: automatically open popup if browser allows it
    try {
      await chrome.action.openPopup();
    } catch (popupErr) {
      console.debug("chrome.action.openPopup() call:", popupErr);
    }

    // Tab stays open; user will handle it via popup or system notification
    return;
  }

  // 2. No captcha — extract and submit
  const results = await chrome.scripting.executeScript({
    target: { tabId },
    func: () => document.documentElement.outerHTML,
  });

  if (results?.[0]?.result) {
    await submitTaskResult(task.task_id, task.url, results[0].result);
  }
}

async function processSingleTaskWithTimeout(task) {
  console.log("Processing task (one tab at a time):", task);
  let tabId = null;
  let timeoutTimer = null;

  try {
    const tab = await chrome.tabs.create({ url: task.url, active: false });
    tabId = tab.id;

    await Promise.race([
      processTabExecution(tabId, task),
      new Promise((_, reject) => {
        timeoutTimer = setTimeout(() => {
          reject(new Error(`Timeout (${TAB_TIMEOUT_MS / 1000}s) exceeded for ${task.url}`));
        }, TAB_TIMEOUT_MS);
      }),
    ]);
  } catch (err) {
    console.error(`Task ${task.task_id} execution error:`, err);
  } finally {
    if (timeoutTimer) clearTimeout(timeoutTimer);
    if (tabId) {
      const map = await getBlockedTabs();
      if (!(tabId in map)) {
        try {
          await chrome.tabs.remove(tabId);
        } catch {}
      }
    }
  }
}

async function processQueue() {
  if (isProcessingQueue) return;
  isProcessingQueue = true;

  try {
    while (taskQueue.length > 0) {
      // If there are blocked tabs (waiting for CAPTCHA), wait until resolved or closed
      while (true) {
        const blocked = await getBlockedTabs();
        if (Object.keys(blocked).length === 0) break;
        await new Promise((r) => setTimeout(r, 1000));
      }

      const task = taskQueue.shift();
      if (!task) continue;

      try {
        await processSingleTaskWithTimeout(task);
      } catch (err) {
        console.error("Error processing task:", task.task_id, err);
      } finally {
        activeTaskIds.delete(task.task_id);
      }

      // Pause/cooldown between tabs to prevent rapid tab bursts and rate-limiting
      if (taskQueue.length > 0) {
        await new Promise((r) => setTimeout(r, COOLDOWN_BETWEEN_TABS_MS));
      }
    }
  } finally {
    isProcessingQueue = false;
  }
}

function enqueueTask(task) {
  if (!task || !task.task_id || activeTaskIds.has(task.task_id)) {
    return;
  }
  activeTaskIds.add(task.task_id);
  taskQueue.push(task);
  processQueue();
}

async function processAllPendingTasks() {
  const tasks = await fetchTasks();
  if (!tasks || tasks.length === 0) return;
  for (const task of tasks) {
    enqueueTask(task);
  }
}

async function connectMercure() {
  if (eventSource) eventSource.close();

  mercureConfig = await fetchMercureConfig();
  if (!mercureConfig) {
    setTimeout(connectMercure, 10000);
    return;
  }

  const url = new URL(mercureConfig.mercure_hub_url);
  url.searchParams.append("topic", mercureConfig.topic);
  eventSource = new EventSource(url.toString());

  eventSource.onopen = () => {
    console.log("Mercure connected");
    processAllPendingTasks();
  };

  eventSource.onmessage = (e) => {
    try {
      const data = JSON.parse(e.data);
      if (data.type === "extension_task") {
        enqueueTask({ task_id: data.task_id, url: data.url, title: data.title });
      }
    } catch (err) {
      console.error("Error parsing Mercure message", err);
    }
  };

  eventSource.onerror = () => {
    eventSource.close();
    eventSource = null;
    setTimeout(connectMercure, 5000);
  };
}

async function sendHeartbeat() {
  try {
    await fetch(`${API_BASE}/api/extension/ping`, {
      method: "POST",
      credentials: "include",
    });
  } catch {}
}

// Initial connection
connectMercure();
sendHeartbeat();

chrome.runtime.onStartup.addListener(() => {
  connectMercure();
  sendHeartbeat();
  setupContextMenu();
});

chrome.alarms.create("keepAlive", { periodInMinutes: 1 });
chrome.alarms.onAlarm.addListener((alarm) => {
  if (alarm.name === "keepAlive") {
    sendHeartbeat();
    if (!eventSource || eventSource.readyState === EventSource.CLOSED) {
      connectMercure();
    }
  }
});

